using NUnit.Framework; using SecondDimension.Presentation.Battle.ArtProduction011; using UnityEngine;
namespace SecondDimension.Tests.EditMode { public sealed class BattleArt011Tests { [Test] public void ManifestAndSpritesAreComplete(){var m=BattleArtManifestLoader011.Load();Assert.That(m.characters,Has.Length.EqualTo(9));foreach(var c in m.characters){Assert.That(c.poses,Has.Length.EqualTo(8));foreach(var p in c.poses)Assert.That(Resources.Load<Sprite>(p.resourcesPath),Is.Not.Null,p.resourcesPath);}} [Test] public void LawsRemainProtected(){var l=BattleArtManifestLoader011.Load().laws;Assert.False(l.changesBattleResolution);Assert.False(l.individualArtSelectableInStandard);Assert.AreEqual(10,l.supportsAlliedUnionSlots);Assert.AreEqual(10,l.supportsEnemyUnionSlots);Assert.False(l.runtimeGenerativeAI);}}}